    up = rotation[:, up_axis] * np.sign(rotation[2, up_axis])
    top_center = centroid + up * side_m / 2
    return {'centroid': centroid, 'surface_centroid': np.mean(cloud, axis=0), 'vertices': vertices, 'vertices_kind': 'inferred_cube_model', 'rotation': rotation, 'side_m': float(side_m), 'top_center': top_center, 'top_normal': up, 'top_vertices': vertices[signs[:, up_axis] == np.sign(rotation[2, up_axis])], 'bottom_z': float(np.min(vertices[:, 2])), 'top_z': float(np.max(vertices[:, 2])), 'observed_face_count': len(faces), 'constrained_axes': constrained, 'plane_rms_m': float(max(plane_rms)), 'inlier_fraction': inlier_fraction, 'reliable': reliable, 'pixel_count': len(cloud)}
